class Span implements Disposable {
  #name: string;
  constructor(name: string) { this.#name = name; trace.start(name); }
  [Symbol.dispose](): void { trace.end(this.#name); }
}

function load(): Data {
  using span = new Span("load");   // ends at scope exit, also on throw
  return fetchData();
}
